$root=dirname(__DIR__);require $root.'/global/config.php';session_set_save_handler(fn()=>true,fn()=>true,fn($id)=>'',fn($id,$data)=>true,fn($id)=>true,fn($max)=>0);app_start_session();require $root.'/global/connection.php';
$userId=(int)$pdo->query('SELECT id FROM tbl_user ORDER BY id LIMIT 1')->fetchColumn();$employeeId=(int)$pdo->query('SELECT id FROM tbl_employee WHERE active_status=1 ORDER BY id LIMIT 1')->fetchColumn();if(!$userId||!$employeeId){fwrite(STDERR,"FAIL request approval: faltan datos base\n");exit(1);}$_SESSION['loggedInUser']=['USERID'=>$userId,'ROLE_CODE'=>'admin','PERMISSIONS'=>[]];$_SERVER['REQUEST_METHOD']='POST';$_SERVER['SCRIPT_NAME']='/modules/aprobaciones/procesar.php';$ids=[];
