 foreach(['APPROVE','REJECT'] as $suffix){$number='QA-SC-'.$suffix.'-'.substr(uniqid(),-6);$pdo->prepare("INSERT INTO tbl_purchase_request(number,status,requester_id,issue_date,required_date,currency,total_estimate,created_by) VALUES(?,'Pendiente',?,?,?,'PEN',10,?)")->execute([$number,$employeeId,date('Y-m-d'),date('Y-m-d'),$userId]);$ids[$suffix]=(int)$pdo->lastInsertId();}
