 $documentHistory=$pdo->prepare("SELECT COUNT(*) FROM tbl_document_status_history WHERE document_type='purchase_request' AND document_id IN (?,?)");$documentHistory->execute([$ids['APPROVE'],$ids['REJECT']]);if((int)$documentHistory->fetchColumn()!==2)throw new RuntimeException('No se registro la trazabilidad documental.');
